/**
 * The site's side of Strapi (the headless counterpart of the WordPress bridge):
 *
 * - change notifications: every write to content (publish, update, delete, media) sends
 *   one signed POST to the site, which clears its page cache (debounced);
 * - languages: the site's locales exist in Strapi, the site's default is Strapi's default;
 * - editor labels: the site pages' fields (generated by `npm run strapi:fields`) get
 *   readable labels and show the site's own copy as the placeholder.
 */
const { createHmac } = require("node:crypto");
const sitePages = require("./site-pages.json");

const WEBHOOK_URL = process.env.HEADLESS_WEBHOOK_URL || "";
const WEBHOOK_SECRET = process.env.HEADLESS_WEBHOOK_SECRET || "";
const WRITE_ACTIONS = new Set(["create", "update", "delete", "publish", "unpublish", "discardDraft"]);

let pending = null;
let changed = new Set();

/** One notification per burst of writes (publishing a localized entry is several writes). */
function notifySite(strapi, uid) {
  if (!WEBHOOK_URL || !WEBHOOK_SECRET) return;
  changed.add(uid);
  if (pending) return;
  pending = setTimeout(async () => {
    const body = JSON.stringify({ event: "change", models: [...changed], at: new Date().toISOString() });
    pending = null;
    changed = new Set();
    try {
      const response = await fetch(WEBHOOK_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Headless-Signature": createHmac("sha256", WEBHOOK_SECRET).update(body, "utf8").digest("base64") },
        body,
        signal: AbortSignal.timeout(5000),
      });
      if (!response.ok) strapi.log.warn(`[headless] site answered ${response.status} to the change notification`);
    } catch (error) {
      strapi.log.warn(`[headless] change notification failed: ${error.message}`);
    }
  }, 300);
}

async function ensureLocales(strapi) {
  const service = strapi.plugin("i18n").service("locales");
  const names = new Intl.DisplayNames(["en"], { type: "language" });
  for (const code of sitePages.locales) {
    if (!(await service.findByCode(code))) await service.create({ code, name: `${names.of(code) ?? code} (${code})` });
  }
  if ((await service.getDefaultLocale()) !== sitePages.defaultLocale) await service.setDefaultLocale({ code: sitePages.defaultLocale });
}

/** Labels, placeholders and descriptions from site-pages.json, on generated types and components. */
async function applyFieldLabels(strapi) {
  const contentManager = strapi.plugin("content-manager");
  const apply = async (service, model, fields) => {
    if (!model) return;
    const configuration = await service.findConfiguration(model);
    const metadatas = configuration.metadatas ?? {};
    let dirty = false;
    for (const [attribute, meta] of Object.entries(fields)) {
      const edit = metadatas[attribute]?.edit;
      if (!edit) continue;
      for (const [key, value] of Object.entries({ label: meta.label, placeholder: meta.placeholder ?? "", description: meta.description ?? "" })) {
        if (edit[key] !== value) {
          edit[key] = value;
          dirty = true;
        }
      }
    }
    const mainField = Object.entries(fields).find(([, meta]) => meta.mainField)?.[0];
    if (mainField && configuration.settings?.mainField !== mainField) {
      configuration.settings.mainField = mainField;
      dirty = true;
    }
    if (dirty) await service.updateConfiguration(model, { settings: configuration.settings, metadatas, layouts: configuration.layouts });
  };
  for (const [uid, fields] of Object.entries(sitePages.labels ?? {})) {
    try {
      if (strapi.contentTypes[uid]) await apply(contentManager.service("content-types"), strapi.contentTypes[uid], fields);
      else if (strapi.components[uid]) await apply(contentManager.service("components"), strapi.components[uid], fields);
    } catch (error) {
      strapi.log.warn(`[headless] labels for ${uid}: ${error.message}`);
    }
  }
}

module.exports = {
  register({ strapi }) {
    strapi.documents.use(async (context, next) => {
      const result = await next();
      if (context.uid.startsWith("api::") && WRITE_ACTIONS.has(context.action)) notifySite(strapi, context.uid);
      return result;
    });
    // Replacing an image or editing its alt text changes pages that show it.
    strapi.db.lifecycles.subscribe({
      models: ["plugin::upload.file"],
      afterUpdate: () => notifySite(strapi, "plugin::upload.file"),
      afterDelete: () => notifySite(strapi, "plugin::upload.file"),
    });
  },

  async bootstrap({ strapi }) {
    await ensureLocales(strapi);
    await applyFieldLabels(strapi);
    if (!WEBHOOK_URL || !WEBHOOK_SECRET) strapi.log.warn("[headless] HEADLESS_WEBHOOK_URL / HEADLESS_WEBHOOK_SECRET not set: the site learns about edits only when its cache expires.");
  },
};
